function sizeViewer(id){const root=$('#'+id),stage=root.querySelector('.image-stage'),img=stage?.querySelector('img');if(!stage||!img?.naturalWidth)return;const base=Math.min((root.clientWidth-30)/img.naturalWidth,(root.clientHeight-30)/img.naturalHeight,1);const scale=id==='objectViewer'?zoom:1;const w=Math.max(1,Math.round(img.naturalWidth*base*scale)),h=Math.max(1,Math.round(img.naturalHeight*base*scale));img.style.width=w+'px';img.style.height=h+'px';stage.style.width=w+'px';stage.style.height=h+'px';root.classList.toggle('zoomed',scale>1);const canvas=stage.querySelector('canvas');canvas.width=w;canvas.height=h;paintRegions(stage);$('#zoomLevel').textContent=zoom===1?'适应画面':Math.round(zoom*100)+'%';}
