$('#saveCaptureRole').onclick=()=>guarded(async()=>{requireCase();const media=current.media.find(m=>m.id===selectedMedia);if(!media)throw Error('先选择本案原照');await api('/api/cases/'+current.id+'/evidence/'+media.id+'/capture-label',{...mutation(),capture_role:$('#captureRole').value,view:media.view},'PATCH');await select(current.id,true);await list();notice('视角声明已保存；原照未改动，旧报告继续使用原资料版本。');});
