$('#upload').onsubmit=event=>{event.preventDefault();guarded(async()=>{requireCase();const fields=new FormData(event.target),files=fields.getAll('file');if(current.media.length+files.length>30)throw Error('档案最多保存30张照片，请选择不超过剩余容量的文件');let saved=0,reused=0,failure=null;for(const file of files){try{const result=await api('/api/cases/'+current.id+'/evidence',{...mutation(),filename:file.name,image_base64:await read64(file),view:fields.get('view'),capture_role:fields.get('capture_role'),edit_declaration:fields.get('edit_declaration'),source:current.source_declaration.length<=1000?current.source_declaration:'完整来源声明见本案档案'});current=result.case;if(result.duplicate_media_id)reused++;else saved++;}catch(error){failure=error;break;}}await select(current.id,true);await list();event.target.reset();if(failure)throw Error('已保存 '+saved+' 张，其余未保存。'+failure.message);$('#uploadDetails').open=false;notice('已保存 '+saved+' 张新原照'+(reused?'，'+reused+' 张重复文件复用已有记录':'')+'。本轮选用 '+analysisDraft.length+' 张；其他照片需勾选并保存后才参与研究。');});};
$('#refreshPreflight').onclick=()=>guarded(async()=>{requireCase();preflight=await api('/api/cases/'+current.id+'/preflight');render();notice('已读取实际像素记录。');});
$('#nvidiaAudit').onclick=()=>guarded(async()=>{requireCase();if(!selectedRun?.assessment)throw Error('先选择已完成意见');nvidiaAuditRecord=await api('/api/cases/'+current.id+'/nvidia-audits',{...mutation(),assessment_run_id:selectedRun.id});nvidiaAuditRecords.unshift(nvidiaAuditRecord);renderNvidiaAudit();notice(nvidiaAuditRecord.state==='succeeded'?'NVIDIA引用核查已执行；只核对身份，不证明结论正确。':nvidiaAuditRecord.error||'NVIDIA引用核查未完成',nvidiaAuditRecord.state!=='succeeded');});
$('#analyze').onclick=()=>guarded(async()=>{requireCase();if(isDocumentary()&&preflight?.next_step==='ask_user')throw Error(preflight.evidence_request?.reason||'文字材料尚需补充，请先登记许可TXT或含正文的固定版本资料');if(!isDocumentary()&&JSON.stringify([...analysisDraft].sort())!==JSON.stringify([...(current.analysis_media_ids||[])].sort()))throw Error('本轮选图尚未保存，请先在图像研究中保存');await api('/api/cases/'+current.id+'/runs',{...mutation(),mode:$('#runMode').value});await select(current.id,true);notice('研判已开始；选用图像、工具调用与意见绑定本轮资料版本。');});
