$('#referenceForm').onsubmit=event=>{event.preventDefault();guarded(async()=>{const fields=new FormData(event.target),file=fields.get('file'),body=Object.fromEntries(fields);delete body.file;await api('/api/references',{...body,request_id:crypto.randomUUID(),filename:file.name,image_base64:await read64(file)});await loadReferences();renderOverview();event.target.reset();notice('图像参照已保存，归属依据与许可按录入内容登记。');});};
