function renderTrace() {
  $('#traceContent').replaceChildren();const run=selectedRun;if(!run)return;
  const history=document.createElement('select');history.setAttribute('aria-label','查看历史运行');for(const r of runs)history.append(makeOption(r.id,`第${r.case_revision}版 · ${labels[r.state]||r.state}`,r.id===run.id));history.onchange=()=>{selectedRun=runs.find(r=>r.id===history.value);render();};
  const strategy=run.versions?.harness?.guided_workflow?'程序材料准备＋模型研判':'模型规划';
  const transport=run.versions?.harness?.compact_actions&&run.versions?.research_task==='visual_research'?' · 精简引用传输':'';
  $('#traceContent').append(history,el('p',`模型调用 ${run.model_calls}/12（含看图） · 工具 ${run.tool_calls}/20 · ${run.mode==='skills'?'领域Skills':'基础规划'} · ${strategy}${transport}`));
  const events=el('div','','event-list');for(const event of run.events){if((event.type==='harness_prepare'&&event.outcome==='started')||(['tool_start','tool_result'].includes(event.type)&&event.actor==='coordinator')||['vision_input','visual_context'].includes(event.type))continue;events.append(el('p',new Date(event.at*1000).toLocaleTimeString()+' · '+traceEventLabel(event)));}$('#traceContent').append(events);
  const details=document.createElement('details');details.append(el('summary','完整版本、观察与工具记录'),el('pre',JSON.stringify(run,null,2)));$('#traceContent').append(details);
}
function traceEventLabel(event){
  const names={read_case:'读取本案',discover_skills:'读取方法目录',load_skill:'加载研究方法',inspect_images:'观察原照',inspect_region:'观察局部',search_knowledge:'检索固定资料',read_knowledge:'阅读资料段落',retrieve_references:'查找图像参照',read_reference:'读取参照',review_dependencies:'读取修订依据',request_evidence:'登记补证事项',record_assessment:'保存研判',record_documentary_findings:'保存文字核查',respond_critic:'回应文字反证',build_opinion:'形成研究报告'};
  const tool=names[event.tool]||event.tool||'';
  if(event.type==='harness_preparation')return '开始程序材料准备（方法与资料由程序选取）';
  if(event.type==='harness_prepare')return '程序准备 · '+tool+' · '+({started:'开始',succeeded:'完成',failed:'失败'}[event.outcome]||'记录');
  if(event.type==='harness_observed_method')return event.selected_method?'程序根据本轮视觉观察选取 '+(skillDisplay[event.selected_method]?.[0]||event.selected_method)+'（器类尚未验证）':'初批视觉观察未触发附加青花方法';
  if(event.type==='harness_budget')return `剩余预算 · 模型 ${event.remaining_model_calls_including_this_request} 次（含本次） · 工具 ${event.remaining_tool_calls} 次 · ${event.remaining_active_seconds} 秒`;
  if(event.type==='model')return (event.purpose==='vision'?'真实图片观察':'模型研判动作')+' · '+(event.outcome==='succeeded'?'请求成功':'请求失败')+(Number.isFinite(event.elapsed)?' · '+event.elapsed.toFixed(2)+' 秒':'');
  if(event.type==='tool_start'||event.type==='tool_result')return (event.actor==='coordinator'?'程序准备':'模型选择')+' · '+tool+' · '+(event.type==='tool_start'?'执行':'返回');
  if(event.type==='visual_context')return '本轮图像准备 · '+(event.assets||[]).length+' 帧';
  if(event.type==='compact_inventory')return `本轮可引用材料 · 观察 ${event.inventory?.totals?.observation_ids||0} 项 · 图像参照 ${event.inventory?.totals?.reference_ids||0} 项 · 已读资料 ${event.inventory?.totals?.knowledge_read_indexes||0} 段（供模型选择）`;
  if(event.type==='transport_expansion')return (event.mappings||[]).length?'绑定 '+event.mappings.length+' 项本轮已读资料身份（保留模型原始判断与理由）':'精简动作结构核验（未扩展资料引用）';
  if(event.type==='validation_error')return '证据或格式检查未通过 · '+String(event.detail||'请回查完整记录').slice(0,120)+' · '+(event.repair_allowed?'允许一次修正':'停止本轮');
  return event.type+(tool?' / '+tool:'');
}
async function loadReferences() {
  references=await api('/api/references');$('#refList').replaceChildren();
  for(const r of references){const item=card(r.title,r.attribution+'\n定位：'+r.locator+'\n依据：'+r.authority+'\n许可：'+(r.permission==='local_use_authorized'?'已确认本地研究':'尚未核实'));const image=document.createElement('img');image.src='/api/media/'+r.media.id+'/display';image.alt=r.title;image.loading='lazy';item.prepend(image);if(/^https?:\/\//i.test(r.source_url)){const link=el('a','查看公开来源');link.href=r.source_url;link.target='_blank';link.rel='noopener';item.append(link);}$('#refList').append(item);}
  if(!references.length)$('#refList').append(el('div','暂无参照。请加入有来源、归属依据与可比图片的标本。','empty-state'));
  if(current)renderImages();
}
function editField(parent, label, value, update, multiline=true) {const wrapper=el('label',label);const input=document.createElement(multiline?'textarea':'input');input.value=value||'';input.oninput=()=>update(input.value);wrapper.append(input);parent.append(wrapper);}
function renderCriticDraft() {
  const root=$('#criticFields');root.replaceChildren();editField(root,'审查问题',criticDraft.question,v=>criticDraft.question=v);
  for(const c of criticDraft.claims){const block=el('fieldset');block.append(el('legend',dimensions[c.dimension]+'主张'));editField(block,'候选归属',c.candidate,v=>c.candidate=v,false);editField(block,'说明与依据',c.reasoning_summary,v=>c.reasoning_summary=v);root.append(block);}
  for(const o of criticDraft.observations){const block=el('fieldset');block.append(el('legend','文字观察（不发送图片）'));editField(block,'可见现象',o.visible,v=>o.visible=v);editField(block,'解释',o.interpretation,v=>o.interpretation=v);editField(block,'限制',o.limitation,v=>o.limitation=v);root.append(block);}
  for(const r of criticDraft.references){const block=el('fieldset');block.append(el('legend','引用资料'));editField(block,'标题',r.title,v=>r.title=v,false);editField(block,'资料定位',r.locator,v=>r.locator=v,false);editField(block,'允许发送的摘录',r.excerpt,v=>r.excerpt=v);root.append(block);}
  $('#criticForm').hidden=false;
}
async function renderPackets() {
  if(!current)return;const packets=await api('/api/cases/'+current.id+'/text-reviews');const root=$('#criticPackets');root.replaceChildren();
  for(const packet of packets){const item=card(labels[packet.state]||packet.state,`本案第${packet.case_revision}版 · ${packet.permission==='public'?'公开文字':'获准脱敏文字'}\n${packet.error||'批准内容已固定，变更须重新准备。'}`);
    const preview=document.createElement('details');preview.append(el('summary','查看实际文字包'),el('pre',JSON.stringify(packet.payload,null,2)));item.append(preview);
    if(packet.state==='prepared'){const button=el('button',criticConfigured?'发送这一份已批准文字':'文字服务待配置','secondary');button.disabled=isDocumentary()||!criticConfigured||packet.case_revision!==current.revision;button.onclick=()=>guarded(async()=>{const request=packet.execute_request_id||crypto.randomUUID();notice('文字审查进行中，器物原图未发送。');await api('/api/text-reviews/'+packet.id+'/execute',{request_id:request,packet_hash:packet.packet_hash});await renderPackets();});item.append(button);}
    if(packet.result){for(const issue of packet.result.issues)item.append(card(dimensions[issue.claim_dimension]+'疑点',issue.concern));item.append(card('补证建议',packet.result.suggested_evidence||'未增加补证建议'),el('p',packet.result.limitations.join('；'),'muted'));const button=el('button','交主 Agent 重看并回应','secondary');button.disabled=packet.case_revision!==current.revision;button.onclick=()=>guarded(async()=>{await api('/api/text-reviews/'+packet.id+'/revise',mutation());await select(current.id,true);tab('opinion');notice('审查疑点已纳入新版本。开始修订后，主 Agent 将结合原图逐项回应。');});item.append(button);}
    root.append(item);
  }
}// Append-only business records use the same local session and revision checks.
