function renderPreparationReviews(){const root=$('#preparationReviewState'),history=$('#preparationReviewHistory');root.replaceChildren();history.replaceChildren();for(const field of $('#preparationReviewForm').elements)field.disabled=!current;if(!current){root.append(inlineEmpty('选择案件后，可复核研究准备材料。'));return;}const unbound=(current.knowledge_document_ids||[]).filter(id=>!current.knowledge_links?.some(link=>link.document_id===id));if(unbound.length)root.append(el('p',unbound.length+' 条旧文字资料关联尚未绑定固定版本。请在资料库核对后重新关联，再导出准备档案。','pin-warning'));const reviews=current.preparation_reviews||[],latest=reviews[reviews.length-1];const stale=!!latest&&latest.case_revision!==current.revision;const state=stale?'stale':latest?.state||'pending';const block=el('div','','preparation-current '+(stale?'stale':''));block.append(el('strong',preparationStates[state]),el('span','当前资料第 '+current.revision+' 版','tag'));if(stale)block.append(el('p','第 '+latest.case_revision+' 版的材料复核记录仍保留。资料已经变化，请核对当前版本后重新记录。'));else if(latest)block.append(el('p',latest.note+'\n依据：'+latest.basis));else block.append(el('p','尚无本版材料复核记录。可独立核对原照、来源凭据与观察材料。'));root.append(block);if(reviews.length){const details=document.createElement('details');details.append(el('summary','查看 '+reviews.length+' 条材料复核记录'));for(const review of [...reviews].reverse()){const item=el('article','','review-history-item');item.append(el('strong','资料第 '+review.case_revision+' 版 · '+preparationStates[review.state]),el('p',review.note+'\n依据：'+review.basis),el('small',(review.reviewer||'操作人')+'（登记身份未认证） · '+recordedTime(review.created_at)));details.append(item);}history.append(details);}}
